"""LLM Client — 带 Token 计量、预算熔断的 LLM 调用封装。

v2.0 重构：TokenMeter 改为 SQLite 后端（core/db.py）。
保留原有 API 接口，LLM 调用仍使用 urllib（标准库）。

v2.1 新增：
- chat/chat_stream 支持 model 参数覆盖（'fast' 或具体模型名）
- AuxiliaryClient 辅助模型路由器
"""
import copy
import json
import logging
import time
import urllib.error
import urllib.request

logger = logging.getLogger("agent.llm")


# ─────────────────────────────────────────────
# Token 计量（SQLite 后端）
# ─────────────────────────────────────────────
class TokenMeter:
    """跟踪 Token 消耗，支持月度预算熔断。

    v2.0: 底层存储从 JSON 文件迁移到 SQLite。
    接受 Database 实例或 meter_path（兼容旧接口）。
    """

    def __init__(self, meter_path_or_db, monthly_cap=50000,
                 warning_threshold=0.8, db=None):
        self.monthly_cap = monthly_cap
        self.warning_threshold = warning_threshold

        if db is not None:
            self.db = db
        else:
            # 兼容旧接口：从 meter_path 创建 Database
            from agent_runtime.core.db import Database
            from pathlib import Path
            db_path = Path(meter_path_or_db)
            # meter_path 是 memory_dir/token_meter.json，
            # 数据库在 memory_dir/../agent.db
            db_file = db_path.parent.parent / 'agent.db'
            self.db = Database(db_file)

    def _current_month(self):
        return time.strftime('%Y-%m')

    def _get_data(self):
        """获取当月计量数据。"""
        month = self._current_month()
        data = self.db.get_token_meter(month)
        if data is None:
            data = {'month': month, 'used': 0,
                    'by_skill': {}, 'by_category': {}}
        return data

    def _save_data(self, data):
        """保存计量数据。"""
        self.db.upsert_token_meter(
            month=data['month'],
            used=data['used'],
            cap=self.monthly_cap,
            by_skill=data.get('by_skill', {}),
            by_category=data.get('by_category', {}))

    def consume(self, tokens, skill='unknown', category='normal'):
        data = self._get_data()
        data['used'] += tokens
        data.setdefault('by_skill', {})
        data['by_skill'][skill] = data['by_skill'].get(skill, 0) + tokens
        data.setdefault('by_category', {})
        data['by_category'][category] = (
            data['by_category'].get(category, 0) + tokens)
        self._save_data(data)

    def remaining(self):
        data = self._get_data()
        return max(0, self.monthly_cap - data.get('used', 0))

    def check_budget(self, requested):
        """返回 True 表示允许调用。"""
        data = self._get_data()
        used = data.get('used', 0)
        if used + requested > self.monthly_cap:
            logger.warning('Token 月度预算即将超限: used=%s requested=%s cap=%s',
                           used, requested, self.monthly_cap)
            return False
        if used > self.monthly_cap * self.warning_threshold:
            logger.warning('Token 消耗已达月度预算的 %.0f%%',
                           self.warning_threshold * 100)
        return True

    def status(self):
        data = self._get_data()
        used = data.get('used', 0)
        return {
            'month': data.get('month', self._current_month()),
            'used': used,
            'cap': self.monthly_cap,
            'remaining': self.remaining(),
            'percent': round(used / self.monthly_cap * 100, 1)
                       if self.monthly_cap > 0 else 0,
            'by_skill': data.get('by_skill', {}),
        }


# ─────────────────────────────────────────────
# LLM 客户端
# ─────────────────────────────────────────────
class LLMClient:
    """统一 LLM 调用入口，所有 Token 消耗经此出口计量。"""

    def __init__(self, config, token_meter=None):
        self.config = config
        self.meter = token_meter or TokenMeter(
            config.token_meter_file,
            monthly_cap=config.get('token_monthly_cap'),
            warning_threshold=config.get('token_warning_threshold'))
        self.timeout = config.get('llm_timeout')

    @staticmethod
    def _estimate_tokens(text):
        """粗略估算 token（中文约 1.5 字/token）。生产建议用 tiktoken。"""
        return max(len(text) // 3, 1)

    def _resolve_model_name(self, model):
        """解析模型名称：None=主模型, 'fast'=快速模型, 字符串=指定模型。"""
        if model is None:
            return self.config.model_name
        if model == 'fast':
            return getattr(self.config, 'fast_model_name', '') or self.config.model_name
        return model  # 直接指定模型名

    def chat(self, messages, tools=None, skill='unknown',
             category='normal', json_mode=False, model=None):
        """调用 OpenAI 兼容 /chat/completions，返回 message 对象。

        model: None=使用主模型, 'fast'=使用快速模型, 字符串=指定模型名
        """
        t_api_start = time.monotonic()
        server = self.config.model_server
        key = self.config.llm_api_key
        model_name = self._resolve_model_name(model)
        if not server or not key or not model_name:
            raise RuntimeError('LLM 未配置（MODEL_SERVER/MODEL_NAME/LLM_API_KEY）')

        # 预算检查
        input_text = ''.join(m.get('content') or '' for m in messages)
        input_tokens = self._estimate_tokens(input_text)
        if not self.meter.check_budget(input_tokens + 2000):
            raise BudgetExceededError(
                'Token 预算不足：剩余 %s' % self.meter.remaining())

        body = {'model': model_name, 'messages': messages,
                'chat_template_kwargs': {'enable_thinking': True}}
        if tools:
            body['tools'] = tools
        if json_mode:
            body['response_format'] = {'type': 'json_object'}

        # ── 详细请求日志 ──
        logger.info('[LLM.chat] >>> model=%s skill=%s msgs=%d tools=%d '
                    'input_chars=%d est_tokens=%d',
                    model_name, skill, len(messages),
                    len(tools) if tools else 0,
                    len(input_text), input_tokens)
        # 打印 system prompt 摘要
        sys_msg = next((m for m in messages if m.get('role') == 'system'), None)
        if sys_msg:
            sc = sys_msg.get('content', '')
            logger.info('[LLM.chat] system_prompt: len=%d preview=%s...',
                        len(sc), sc[:200].replace('\n', '\\n'))
        # 打印对话历史摘要
        for i, m in enumerate(messages):
            role = m.get('role', '?')
            content = (m.get('content') or '')[:120].replace('\n', '\\n')
            tc = m.get('tool_calls')
            extra = ''
            if tc:
                extra = ' tool_calls=%s' % [
                    t.get('function', {}).get('name', '?') for t in tc]
            if role == 'tool':
                extra = ' tool_call_id=%s' % m.get('tool_call_id', '?')
            logger.info('[LLM.chat]   msg[%d] role=%s len=%d content=%s%s',
                        i, role, len(m.get('content') or ''), content, extra)
        # 打印 tools schema 名称
        if tools:
            tool_names = [t.get('function', {}).get('name', '?') for t in tools]
            logger.info('[LLM.chat] tools=%s', tool_names)

        req = urllib.request.Request(
            server + '/chat/completions',
            data=json.dumps(body, ensure_ascii=False).encode('utf-8'),
            headers={'Content-Type': 'application/json',
                     'Authorization': 'Bearer %s' % key})
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                data = json.loads(resp.read().decode('utf-8'))
        except urllib.error.HTTPError as e:
            # 快速模型不可用时降级到主模型
            if e.code == 401 and model == 'fast' and model_name != self.config.model_name:
                logger.warning('[LLM.chat] 快速模型 %s 不可用(401)，降级到主模型 %s',
                               model_name, self.config.model_name)
                body['model'] = self.config.model_name
                req = urllib.request.Request(
                    server + '/chat/completions',
                    data=json.dumps(body, ensure_ascii=False).encode('utf-8'),
                    headers={'Content-Type': 'application/json',
                             'Authorization': 'Bearer %s' % key})
                with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                    data = json.loads(resp.read().decode('utf-8'))
                model_name = self.config.model_name
            else:
                raise

        t_api_end = time.monotonic()
        message = data['choices'][0]['message']
        # 存储 reasoning_content 供调用方访问
        self._last_reasoning = message.get('reasoning_content') or ''
        out_tokens = self._estimate_tokens(message.get('content') or '')
        self.meter.consume(input_tokens + out_tokens,
                           skill=skill, category=category)

        # ── 详细响应日志 ──
        resp_content = (message.get('content') or '')[:200].replace('\n', '\\n')
        resp_tc = message.get('tool_calls')
        tc_info = ''
        if resp_tc:
            tc_info = ' tool_calls=%s' % [
                '%s(%s)' % (t.get('function', {}).get('name', '?'),
                            t.get('function', {}).get('arguments', '')[:80])
                for t in resp_tc]
        logger.info('[LLM.chat] <<< model=%s skill=%s API耗时=%.1fms '
                    'tokens(in=%d+out=%d=%d) content=%s%s',
                    model_name, skill, (t_api_end - t_api_start) * 1000,
                    input_tokens, out_tokens, input_tokens + out_tokens,
                    resp_content, tc_info)
        return message

    def quick_prompt(self, system, user, skill='unknown',
                     category='normal', json_mode=False, model=None):
        """快捷调用：system + user 文本，返回 content 字符串。

        model: None=使用主模型, 'fast'=使用快速模型
        """
        message = self.chat(
            messages=[{'role': 'system', 'content': system},
                      {'role': 'user', 'content': user}],
            skill=skill, category=category, json_mode=json_mode,
            model=model)
        return message.get('content') or ''

    def chat_stream(self, messages, tools=None, skill='unknown',
                    category='normal', model=None, cancel_event=None):
        """流式调用 OpenAI 兼容 /chat/completions，yield 每个增量文本 chunk。

        使用 SSE (Server-Sent Events) 解析流式响应。
        调用方负责将 chunk 拼接为完整回复并计量 Token。
        model: None=使用主模型, 'fast'=使用快速模型

        流式完成后，通过 gen.tool_calls 获取工具调用列表（如有）。
        """
        t_llm_start = time.monotonic()
        server = self.config.model_server
        key = self.config.llm_api_key
        model_name = self._resolve_model_name(model)
        if not server or not key or not model_name:
            raise RuntimeError('LLM 未配置（MODEL_SERVER/MODEL_NAME/LLM_API_KEY）')

        # 预算检查
        input_text = ''.join(m.get('content') or '' for m in messages)
        input_tokens = self._estimate_tokens(input_text)
        if not self.meter.check_budget(input_tokens + 2000):
            raise BudgetExceededError(
                'Token 预算不足：剩余 %s' % self.meter.remaining())

        body = {
            'model': model_name,
            'messages': messages,
            'stream': True,
            'chat_template_kwargs': {'enable_thinking': True},
        }
        if tools:
            body['tools'] = tools

        # ── 详细请求日志 ──
        logger.info('[LLM.stream] >>> model=%s skill=%s msgs=%d tools=%d '
                    'input_chars=%d est_tokens=%d',
                    model_name, skill, len(messages),
                    len(tools) if tools else 0,
                    len(input_text), input_tokens)
        sys_msg = next((m for m in messages if m.get('role') == 'system'), None)
        if sys_msg:
            sc = sys_msg.get('content', '')
            logger.info('[LLM.stream] system_prompt: len=%d preview=%s...',
                        len(sc), sc[:200].replace('\n', '\\n'))
        for i, m in enumerate(messages):
            role = m.get('role', '?')
            content = (m.get('content') or '')[:120].replace('\n', '\\n')
            tc = m.get('tool_calls')
            extra = ''
            if tc:
                extra = ' tool_calls=%s' % [
                    t.get('function', {}).get('name', '?') for t in tc]
            if role == 'tool':
                extra = ' tool_call_id=%s' % m.get('tool_call_id', '?')
            logger.info('[LLM.stream]   msg[%d] role=%s len=%d content=%s%s',
                        i, role, len(m.get('content') or ''), content, extra)
        if tools:
            tool_names = [t.get('function', {}).get('name', '?') for t in tools]
            logger.info('[LLM.stream] tools=%s', tool_names)

        req = urllib.request.Request(
            server + '/chat/completions',
            data=json.dumps(body, ensure_ascii=False).encode('utf-8'),
            headers={'Content-Type': 'application/json',
                     'Authorization': 'Bearer %s' % key})

        total_output_chars = 0
        chunk_count = 0
        t_first_byte = None
        # 收集流式工具调用
        collected_tool_calls = []
        tool_call_accum = {}  # index -> {id, function: {name, arguments}}

        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            for raw_line in resp:
                if cancel_event is not None and cancel_event.is_set():
                    resp.close()
                    logger.info('[LLM.stream] 收到取消信号，中断流式读取')
                    break
                raw_line = raw_line.strip()
                if not raw_line:
                    continue
                # SSE 格式: "data: {...}" 或 "data: [DONE]"
                if raw_line.startswith(b'data: '):
                    payload = raw_line[6:]
                    if payload == b'[DONE]':
                        break
                    try:
                        chunk = json.loads(payload)
                    except (json.JSONDecodeError, ValueError):
                        continue
                    choices = chunk.get('choices', [])
                    if not choices:
                        continue
                    delta = choices[0].get('delta', {})
                    # 收集流式工具调用
                    delta_tc = delta.get('tool_calls')
                    if delta_tc:
                        for tc_delta in delta_tc:
                            idx = tc_delta.get('index', 0)
                            if idx not in tool_call_accum:
                                tool_call_accum[idx] = {
                                    'id': tc_delta.get('id', ''),
                                    'type': 'function',
                                    'function': {
                                        'name': tc_delta.get('function', {}).get('name', ''),
                                        'arguments': tc_delta.get('function', {}).get('arguments', ''),
                                    }
                                }
                            else:
                                # 追加增量参数
                                fn_delta = tc_delta.get('function', {})
                                if fn_delta.get('arguments'):
                                    tool_call_accum[idx]['function']['arguments'] += fn_delta['arguments']
                                if fn_delta.get('name'):
                                    tool_call_accum[idx]['function']['name'] = fn_delta['name']
                    # 思考内容（reasoning）
                    reasoning = delta.get('reasoning_content', '')
                    if reasoning:
                        if t_first_byte is None:
                            t_first_byte = time.monotonic()
                            logger.info('[计时] LLM TTFB=%.1fms model=%s',
                                        (t_first_byte - t_llm_start) * 1000,
                                        model_name)
                        yield ('reasoning', reasoning)
                    # 正文内容
                    content = delta.get('content', '')
                    if content:
                        if t_first_byte is None:
                            t_first_byte = time.monotonic()
                            logger.info('[计时] LLM TTFB=%.1fms model=%s',
                                        (t_first_byte - t_llm_start) * 1000,
                                        model_name)
                        total_output_chars += len(content)
                        chunk_count += 1
                        yield ('content', content)

        # 汇总工具调用
        if tool_call_accum:
            collected_tool_calls = [
                tool_call_accum[idx]
                for idx in sorted(tool_call_accum.keys())
            ]
            logger.info('[LLM.stream] 检测到流式工具调用: %s',
                        [tc['function']['name'] for tc in collected_tool_calls])

        t_llm_end = time.monotonic()
        # 流式完成后计量 Token
        out_tokens = self._estimate_tokens(
            'x' * total_output_chars)  # 按总字符数估算
        self.meter.consume(input_tokens + out_tokens,
                           skill=skill, category=category)
        logger.info('[\u8ba1\u65f6] LLM stream\u5b8c\u6210: model=%s skill=%s chunks=%d chars=%d '
                    'TTFB=%.1fms \u603b\u8017\u65f6=%.1fms tokens~=%s tool_calls=%d',
                    model_name, skill, chunk_count, total_output_chars,
                    (t_first_byte - t_llm_start) * 1000 if t_first_byte else 0,
                    (t_llm_end - t_llm_start) * 1000,
                    input_tokens + out_tokens,
                    len(collected_tool_calls))

        # 将工具调用附加到生成器对象，调用方可通过 gen.tool_calls 获取
        self._last_stream_tool_calls = collected_tool_calls


# ─────────────────────────────────────────────
# 异常
# ─────────────────────────────────────────────
class LLMError(Exception):
    pass


class LLMCallError(LLMError):
    pass


class BudgetExceededError(LLMError):
    pass


# ─────────────────────────────────────────────
# 辅助模型路由器
# ─────────────────────────────────────────────
class AuxiliaryClient:
    """辅助任务模型路由器。

    为不同任务类型选择最优模型：
    - decompose/complexity: 复杂度评估 → FAST_MODEL
    - router/classify: 意图分类 → FAST_MODEL
    - summarize: 摘要压缩 → FAST_MODEL
    - chat: 主对话 → SMART_MODEL（默认）
    """

    def __init__(self, config, primary_client):
        self.config = config
        self.primary = primary_client
        self._fast_client = None  # 延迟创建

    def get_client(self, task='chat'):
        """根据任务类型返回对应 LLMClient 实例。"""
        if task == 'chat':
            return self.primary
        return self._get_or_create_fast_client()

    def _get_or_create_fast_client(self):
        """创建或返回快速模型客户端（复用主客户端配置，只换 model_name）。"""
        if self._fast_client is not None:
            return self._fast_client
        fast_model = getattr(self.config, 'fast_model_name', '') or self.config.model_name
        # 快速模型与主模型相同时，直接复用主客户端
        if fast_model == self.config.model_name:
            logger.info('AuxiliaryClient: 快速模型与主模型相同(%s)，复用主客户端', fast_model)
            return self.primary
        # 复用主客户端的 meter 和 timeout
        self._fast_client = LLMClient(self.config, self.primary.meter)
        # 覆盖 model_name 为快速模型
        self._fast_client.config = copy.copy(self.config)
        self._fast_client.config.model_name = fast_model
        logger.info('AuxiliaryClient: 快速模型客户端已创建 model=%s', fast_model)
        return self._fast_client
